55	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	const sumOf = <T>(values: readonly T[], amountOf: (value: T) => number): number =>
65	  values.reduce((sum, value) => sum + amountOf(value), 0);
66	
67	const itemBasePremiumOf = (item: Item): number =>
68	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
69	
70	const BLOCK_PREMIUM = 60;
71	const BLOCK_SIZE = 3;
72	
73	const itemsGroupedByType = (
74	  items: readonly Item[],
75	): readonly (readonly Item[])[] => [
76	  ...items
77	    .reduce(
78	      (groups, item) =>
79	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
80	      new Map<string, readonly Item[]>(),
81	    )
82	    .values(),
83	];
84	
85	const groupBasePremiumOf = (group: readonly Item[]): number =>
86	  group.length === BLOCK_SIZE
87	    ? BLOCK_PREMIUM
88	    : sumOf(group, itemBasePremiumOf);
89	
90	const CURSED_SURCHARGE_RATE = 0.5;
91	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
92	const SURCHARGED_ENCHANTMENT_LEVEL = 5;
93	
94	const cursedSurchargeOf = (item: Item): number =>
95	  item.cursed === true ? itemBasePremiumOf(item) * CURSED_SURCHARGE_RATE : 0;
96	
97	const highEnchantmentSurchargeOf = (item: Item): number =>
98	  item.enchantment === SURCHARGED_ENCHANTMENT_LEVEL
99	    ? itemBasePremiumOf(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
100	    : 0;
101	
102	const itemSurchargeOf = (item: Item): number =>
103	  cursedSurchargeOf(item) + highEnchantmentSurchargeOf(item);
104	
105	const policyBasePremiumOf = (items: readonly Item[]): number =>
106	  sumOf(itemsGroupedByType(items), groupBasePremiumOf);
107	
108	const policySurchargeOf = (items: readonly Item[]): number =>
109	  sumOf(items, itemSurchargeOf);
110	
111	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
112	
113	const firstInsuranceSurchargeOf = (basePremium: number): number =>
114	  basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
115	
116	const LOYALTY_DISCOUNT_RATE = 0.2;
117	const LOYALTY_YEARS_THRESHOLD = 2;
118	
119	const loyaltyDiscountOf = (basePremium: number, customer: Customer): number =>
120	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
121	    ? basePremium * LOYALTY_DISCOUNT_RATE
122	    : 0;
123	
124	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
125	
126	const followUpDiscountOf = (
127	  basePremium: number,
128	  previousQuoteCount: number,
129	): number =>
130	  previousQuoteCount > 0 ? basePremium * FOLLOW_UP_DISCOUNT_RATE : 0;
131	
132	const premiumBeforeFeeOf = (
133	  items: readonly Item[],
134	  customer: Customer,
135	  previousQuoteCount: number,
136	): number => {
137	  const basePremium = policyBasePremiumOf(items);
138	
139	  return (
140	    basePremium +
141	    policySurchargeOf(items) +
142	    firstInsuranceSurchargeOf(basePremium) -
143	    loyaltyDiscountOf(basePremium, customer) -
144	    followUpDiscountOf(basePremium, previousQuoteCount)
145	  );
146	};
147	
148	const PROCESSING_FEE = 5;
149	
150	const quotePremiumOf = (
151	  items: readonly Item[],
152	  customer: Customer,
153	  previousQuoteCount: number,
154	): number =>
155	  Math.ceil(
156	    premiumBeforeFeeOf(items, customer, previousQuoteCount) + PROCESSING_FEE,
157	  );
158	
159	export const runScenario = (scenario: Scenario): ScenarioResult => ({
160	  results: scenario.steps.map((step, stepIndex) => ({
161	    premium: quotePremiumOf(
162	      (step as QuoteStep).items,
163	      scenario.customer,
164	      stepIndex,
165	    ),
166	  })),
167	});
