const B={sword:100,amulet:60,staff:80,potion:40,rune:25,moonstone:25};
const types=Object.keys(B);
// enumerate small policies: counts per type 0..3, flags cursed/ench5 on one item of a type
// simpler: brute force item lists up to 3 items with modifiers
const mods=[{},{cursed:true},{enchantment:5},{cursed:true,enchantment:5}];
const items=[];
for(const t of types) for(const m of mods) items.push({type:t,...m});
const combos=[];
function rec(start,cur){ if(cur.length>0) combos.push([...cur]); if(cur.length===3) return; for(let i=start;i<items.length;i++){cur.push(items[i]);rec(i,cur);cur.pop();}}
rec(0,[]);
const groupBase=(g)=> g.length===3?60:g.reduce((s,i)=>s+B[i.type],0);
const policyBase=(l)=>{const m=new Map();for(const i of l){m.set(i.type,[...(m.get(i.type)||[]),i]);}return [...m.values()].reduce((s,g)=>s+groupBase(g),0);};
const sur=(l)=>l.reduce((s,i)=>s+(i.cursed?B[i.type]*0.5:0)+(i.enchantment===5?B[i.type]*0.3:0),0);
const out=[];
for(const l of combos) for(const years of [0,2]) for(const prev of [0,1]){
  const b=policyBase(l);
  const p=b+sur(l)+0.1*b-(years>=2?0.2*b:0)-(prev>0?0.15*b:0)+5;
  const f=p-Math.floor(p);
  if(f>0.001&&f<0.499) out.push({l:l.map(i=>i.type+(i.cursed?"*":"")+(i.enchantment===5?"e5":"")).join("+"),years,prev,p});
}
out.sort((a,b)=>a.l.length-b.l.length);
console.log(out.slice(0,15));
'

